examples.source:
fn main(x: i32) -> i32 {
    if x > 0 {
        return 1;
    } else {
        return 2;
    }
    return 3;
}

standard.code:
fn main(x: i32) -> i32 {
    if x > 0 {
        return 1;
    } else {
        return 2;
    }
    return 3;
}

my-syntax.code:
function main(x: i32) -> i32 {
    when x > 0 {
        give 1;
    } otherwise {
        give 2;
    }
    give 3;
}

